#!/usr/bin/env node
/**
 * generate-build-meta.mjs — Single source of truth for version/build metadata.
 *
 * Run automatically as part of `npm run build` (before `vite build`) and by
 * CI. Writes:
 *
 *   src/buildMeta.js       — ES module imported by the frontend
 *   api/_lib/buildInfo.js  — CommonJS-safe ES module imported by API functions
 *
 * Both files are generated from package.json + git + clock, so the frontend,
 * API and PWA can never disagree about what version is running.
 *
 * The generated files are committed (not gitignored) so that local dev, CI
 * without git history (shallow clone) and Vercel builds all produce a
 * meaningful `commit`. `npm run build` always regenerates them, and CI
 * (ci.yml) does not fail if regeneration produces no diff (see the
 * "Regenerate build metadata" step that runs before format:check).
 *
 * Fallbacks: no git (shallow/CI) → "unknown"; commit overridden by env var
 * VERCEL_GIT_COMMIT_SHA (Vercel always provides it, including the real SHA
 * for GitHub-connected deployments).
 */

import { readFileSync, writeFileSync } from "fs";
import { execSync } from "child_process";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

const pkg = JSON.parse(readFileSync(resolve(root, "package.json"), "utf-8"));
const version = pkg.version;

let commit = process.env.VERCEL_GIT_COMMIT_SHA || "";
if (!commit) {
  try {
    commit = execSync("git rev-parse HEAD", { cwd: root, stdio: ["pipe", "pipe", "pipe"] }).toString().trim();
  } catch {
    commit = "";
  }
}
if (!commit) commit = "unknown";
commit = commit.slice(0, 7);

const buildTime = new Date().toISOString();

const banner = `// AUTO-GENERATED by scripts/generate-build-meta.mjs — DO NOT EDIT BY HAND.
// Regenerated on every \`npm run build\` from package.json + git.
// App version ${version}, commit ${commit}, built ${buildTime}.
`;

const frontend = `${banner}
export const APP_VERSION = "${version}";
export const BUILD_COMMIT = "${commit}";
export const BUILD_TIME = "${buildTime}";

// Convenience object for About/System Information panels and diagnostics.
export const BUILD_META = {
  appVersion: APP_VERSION,
  commit: BUILD_COMMIT,
  buildTime: BUILD_TIME,
};
`;

// API module: same values, ESM (Vercel functions are ESM in this repo —
// api/*.js files use import/export).
const apiModule = `${banner}
export const BUILD_INFO = {
  version: "${version}",
  commit: "${commit}",
  buildTime: "${buildTime}",
};
`;

writeFileSync(resolve(root, "src", "buildMeta.js"), frontend, "utf-8");
writeFileSync(resolve(root, "api", "_lib", "buildInfo.js"), apiModule, "utf-8");

console.log(`[build-meta] version=${version} commit=${commit} buildTime=${buildTime}`);
